(function (root, factory) {
  const api = factory();

  if (typeof module === "object" && module.exports) {
    module.exports = api;
  }

  if (root) {
    root.LiveCallValidity = api;
  }
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  const SOURCE_TIMEZONE = "America/New_York";
  const DISPLAY_TIMEZONE = "Europe/London";
  const DEFAULT_REFRESH_SCHEDULE = "07:00";
  const DEFAULT_EXECUTION_CLOCK = "07:00 ET primary run";
  const DEFAULT_HORIZON_DURATION = "PT24H";
  const DEFAULT_PROVISIONAL_REFRESH_NOTE = "No authoritative orchestrator cron exists in the repository";
  const DEFAULT_HORIZON_NOTE = "Weekday-active-time V1 excludes weekend-closed hours only. Exchange holidays and intraday maintenance breaks are not yet modelled.";
  const WEEKDAY_ACTIVE_MARKET_CALENDAR = "WEEKDAY_ACTIVE_TIME_V1";
  const CRYPTO_MARKET_CALENDAR = "CRYPTO_24_7";
  const WEEKEND_BLOCKED_ASSETS = new Set(["USD", "EUR", "GOLD", "NQ"]);
  const EXPLICIT_NO_CALL_DIRECTIONS = new Set(["NO CALL", "NO 24H CALL"]);

  function parseIso(value) {
    if (!value) return null;
    const date = value instanceof Date ? value : new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  function firstPresentValue(...values) {
    for (const value of values) {
      if (value !== null && value !== undefined && value !== "") {
        return value;
      }
    }
    return null;
  }

  function parseExecutionClockLabel(label = DEFAULT_EXECUTION_CLOCK) {
    const match = String(label || "").match(/(\d{1,2}):(\d{2})\s*ET/i);
    return {
      hour: match ? Number(match[1]) : 7,
      minute: match ? Number(match[2]) : 0
    };
  }

  function getZonedParts(date, timeZone) {
    const formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false
    });
    const parts = formatter.formatToParts(date);
    const lookup = Object.fromEntries(parts.map((part) => [part.type, part.value]));
    return {
      year: Number(lookup.year),
      month: Number(lookup.month),
      day: Number(lookup.day),
      hour: Number(lookup.hour),
      minute: Number(lookup.minute),
      second: Number(lookup.second)
    };
  }

  function zonedWeekdayName(date, timeZone = SOURCE_TIMEZONE) {
    const parsed = parseIso(date);
    if (!parsed) return "";
    return parsed.toLocaleDateString("en-US", {
      timeZone,
      weekday: "long"
    });
  }

  function zonedWeekdayIndex(date, timeZone = SOURCE_TIMEZONE) {
    const weekday = zonedWeekdayName(date, timeZone);
    return {
      Sunday: 0,
      Monday: 1,
      Tuesday: 2,
      Wednesday: 3,
      Thursday: 4,
      Friday: 5,
      Saturday: 6
    }[weekday] ?? -1;
  }

  function isWeekendInTimeZone(date, timeZone = SOURCE_TIMEZONE) {
    const weekdayIndex = zonedWeekdayIndex(date, timeZone);
    return weekdayIndex === 0 || weekdayIndex === 6;
  }

  function parseOffsetMinutes(offsetLabel) {
    const match = String(offsetLabel || "").match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/i);
    if (!match) return 0;
    const sign = match[1] === "-" ? -1 : 1;
    const hours = Number(match[2] || 0);
    const minutes = Number(match[3] || 0);
    return sign * ((hours * 60) + minutes);
  }

  function getOffsetMinutes(date, timeZone) {
    const formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hour: "2-digit",
      minute: "2-digit",
      timeZoneName: "shortOffset",
      hour12: false
    });
    const offsetPart = formatter.formatToParts(date).find((part) => part.type === "timeZoneName");
    return parseOffsetMinutes(offsetPart?.value || "GMT+0");
  }

  function zonedDateTimeToUtc(parts, timeZone) {
    let utcMs = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second || 0, 0);

    for (let i = 0; i < 4; i += 1) {
      const offsetMinutes = getOffsetMinutes(new Date(utcMs), timeZone);
      const adjustedUtcMs = Date.UTC(
        parts.year,
        parts.month - 1,
        parts.day,
        parts.hour,
        parts.minute,
        parts.second || 0,
        0
      ) - (offsetMinutes * 60000);

      if (adjustedUtcMs === utcMs) break;
      utcMs = adjustedUtcMs;
    }

    return new Date(utcMs);
  }

  function addZonedDays(parts, days) {
    const utcDate = new Date(Date.UTC(parts.year, parts.month - 1, parts.day));
    utcDate.setUTCDate(utcDate.getUTCDate() + days);
    return {
      year: utcDate.getUTCFullYear(),
      month: utcDate.getUTCMonth() + 1,
      day: utcDate.getUTCDate()
    };
  }

  function computeNextRefreshDueAt(sealedAtValue, executionClockLabel = DEFAULT_EXECUTION_CLOCK, timeZone = SOURCE_TIMEZONE) {
    const sealedAt = parseIso(sealedAtValue);
    if (!sealedAt) return null;

    const executionClock = parseExecutionClockLabel(executionClockLabel);
    const sealedParts = getZonedParts(sealedAt, timeZone);
    let dueParts = {
      year: sealedParts.year,
      month: sealedParts.month,
      day: sealedParts.day,
      hour: executionClock.hour,
      minute: executionClock.minute,
      second: 0
    };
    let dueAt = zonedDateTimeToUtc(dueParts, timeZone);

    if (dueAt.getTime() <= sealedAt.getTime()) {
      const nextDay = addZonedDays(sealedParts, 1);
      dueParts = {
        ...nextDay,
        hour: executionClock.hour,
        minute: executionClock.minute,
        second: 0
      };
      dueAt = zonedDateTimeToUtc(dueParts, timeZone);
    }

    return dueAt.toISOString();
  }

  function isWeekendBlockedAsset(asset = "") {
    return WEEKEND_BLOCKED_ASSETS.has(String(asset || "").toUpperCase());
  }

  function assetUsesWeekdayActiveExpiry(asset = "") {
    return isWeekendBlockedAsset(asset);
  }

  function assetHorizonBasis(asset = "") {
    return assetUsesWeekdayActiveExpiry(asset) ? "WEEKDAY_ACTIVE_TIME_V1" : "WALL_CLOCK";
  }

  function assetMarketCalendar(asset = "") {
    return assetUsesWeekdayActiveExpiry(asset) ? WEEKDAY_ACTIVE_MARKET_CALENDAR : CRYPTO_MARKET_CALENDAR;
  }

  function normalizeDirection(direction = "") {
    return String(direction || "").trim().toUpperCase();
  }

  function isExplicitNoCallDirection(direction = "") {
    return EXPLICIT_NO_CALL_DIRECTIONS.has(normalizeDirection(direction));
  }

  function isPendingDirection(direction = "") {
    return normalizeDirection(direction) === "PENDING" || normalizeDirection(direction) === "";
  }

  function isNoCallDirection(direction = "") {
    return isExplicitNoCallDirection(direction) || isPendingDirection(direction);
  }

  function chooseSealedAt(agent = {}) {
    return agent.sealed_at || agent.full_output?.created_at || agent.last_run_et || agent.created_at || null;
  }

  function chooseGeneratedAt(agent = {}) {
    return agent.generated_at || agent.last_run_et || chooseSealedAt(agent);
  }

  function chooseSourceRunId(agent = {}) {
    return agent.source_run_id || agent.full_output?.source_run_id || agent.full_output?.execution_id || agent.full_output?.workflow_execution_id || null;
  }

  function provisionalScheduleMetadata(dashboardMeta = {}) {
    const clock = parseExecutionClockLabel(dashboardMeta.execution_clock || DEFAULT_EXECUTION_CLOCK);
    const refreshSchedule = `${String(clock.hour).padStart(2, "0")}:${String(clock.minute).padStart(2, "0")}`;
    return {
      refresh_schedule: dashboardMeta.refresh_schedule || refreshSchedule || DEFAULT_REFRESH_SCHEDULE,
      refresh_timezone: dashboardMeta.refresh_timezone || SOURCE_TIMEZONE,
      refresh_schedule_status: dashboardMeta.refresh_schedule_status || "PROVISIONAL",
      validity_schedule_source: dashboardMeta.validity_schedule_source || "dashboard_meta.execution_clock",
      validity_schedule_note: dashboardMeta.validity_schedule_note || DEFAULT_PROVISIONAL_REFRESH_NOTE
    };
  }

  function nextWeekdayOpenFrom(value, timeZone = SOURCE_TIMEZONE) {
    const current = parseIso(value);
    if (!current) return null;

    const currentParts = getZonedParts(current, timeZone);
    const weekdayIndex = zonedWeekdayIndex(current, timeZone);
    let daysToAdd = 0;

    if (weekdayIndex === 6) {
      daysToAdd = 2;
    } else if (weekdayIndex === 0) {
      daysToAdd = 1;
    } else {
      return current;
    }

    const nextDay = addZonedDays(currentParts, daysToAdd);
    return zonedDateTimeToUtc({
      ...nextDay,
      hour: 0,
      minute: 0,
      second: 0
    }, timeZone);
  }

  function weekendStartFromWeekday(value, timeZone = SOURCE_TIMEZONE) {
    const current = parseIso(value);
    if (!current) return null;
    const currentParts = getZonedParts(current, timeZone);
    const weekdayIndex = zonedWeekdayIndex(current, timeZone);
    if (weekdayIndex < 1 || weekdayIndex > 5) return current;

    const daysToSaturday = 6 - weekdayIndex;
    const saturday = addZonedDays(currentParts, daysToSaturday);
    return zonedDateTimeToUtc({
      ...saturday,
      hour: 0,
      minute: 0,
      second: 0
    }, timeZone);
  }

  function computeWeekdayActiveForecastWindowEnd(sealedAtValue, activeDurationMs, timeZone = SOURCE_TIMEZONE) {
    let cursor = parseIso(sealedAtValue);
    if (!cursor) return null;

    let remainingMs = activeDurationMs;

    while (remainingMs > 0) {
      if (isWeekendInTimeZone(cursor, timeZone)) {
        cursor = nextWeekdayOpenFrom(cursor, timeZone);
        continue;
      }

      const weekendStart = weekendStartFromWeekday(cursor, timeZone);
      if (!weekendStart) return null;

      const activeChunkMs = Math.min(remainingMs, weekendStart.getTime() - cursor.getTime());
      cursor = new Date(cursor.getTime() + activeChunkMs);
      remainingMs -= activeChunkMs;

      if (remainingMs > 0) {
        cursor = nextWeekdayOpenFrom(weekendStart, timeZone);
      }
    }

    return cursor.toISOString();
  }

  function computeForecastWindowEnd(sealedAtValue, asset = "", horizonDuration = DEFAULT_HORIZON_DURATION) {
    const sealedAt = parseIso(sealedAtValue);
    if (!sealedAt) return null;

    if (horizonDuration !== DEFAULT_HORIZON_DURATION) return null;

    if (!assetUsesWeekdayActiveExpiry(asset)) {
      return new Date(sealedAt.getTime() + (24 * 60 * 60 * 1000)).toISOString();
    }

    return computeWeekdayActiveForecastWindowEnd(sealedAt, 24 * 60 * 60 * 1000, SOURCE_TIMEZONE);
  }

  function deriveLayer1StatusAtBuild(agent = {}, dashboardMeta = {}) {
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const direction = priorityCall.direction;
    const sealedAt = chooseSealedAt(agent);
    const statusAtBuild = String(agent.status_at_build || priorityCall.status_at_build || "").toUpperCase();

    if (statusAtBuild) return statusAtBuild;
    if (!sealedAt || isPendingDirection(direction)) return "UNAVAILABLE";
    if (isWeekendBlockedAsset(agent.agent) && isWeekendInTimeZone(sealedAt, SOURCE_TIMEZONE) && isExplicitNoCallDirection(direction)) {
      return "MARKET_CLOSED";
    }
    if (isExplicitNoCallDirection(direction)) return "NO_CALL";
    return "ACTIVE";
  }

  function buildLayer1Timing(agent = {}, dashboardMeta = {}) {
    const executionClock = dashboardMeta.execution_clock || DEFAULT_EXECUTION_CLOCK;
    const scheduleMeta = provisionalScheduleMetadata(dashboardMeta);
    const generatedAt = chooseGeneratedAt(agent);
    const sealedAt = chooseSealedAt(agent);
    const validFrom = agent.valid_from || sealedAt;
    const refreshDueAt = agent.refresh_due_at || computeNextRefreshDueAt(validFrom || sealedAt, executionClock, SOURCE_TIMEZONE);
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const horizonCode = agent.horizon_code || priorityCall.horizon_code || "24H";
    const horizonDuration = agent.horizon_duration || priorityCall.horizon_duration || DEFAULT_HORIZON_DURATION;
    const horizonBasis = agent.horizon_basis || priorityCall.horizon_basis || assetHorizonBasis(agent.agent);
    const marketCalendar = agent.market_calendar || priorityCall.market_calendar || assetMarketCalendar(agent.agent);
    const explicitForecastWindowEnd = firstPresentValue(
      agent.forecast_window_end,
      priorityCall.forecast_window_end,
      agent.expires_at,
      priorityCall.expires_at
    );
    const forecastWindowEnd = explicitForecastWindowEnd ?? computeForecastWindowEnd(validFrom || sealedAt, agent.agent, horizonDuration);
    const statusAtBuild = deriveLayer1StatusAtBuild(agent, dashboardMeta);

    return {
      generated_at: generatedAt,
      sealed_at: sealedAt,
      valid_from: validFrom,
      refresh_due_at: refreshDueAt,
      forecast_window_end: forecastWindowEnd,
      expires_at: forecastWindowEnd,
      status_at_build: statusAtBuild,
      effective_status: String(agent.effective_status || priorityCall.effective_status || statusAtBuild).toUpperCase(),
      status_resolved_at: agent.status_resolved_at || priorityCall.status_resolved_at || null,
      horizon_code: horizonCode,
      horizon_duration: horizonDuration,
      horizon_basis: horizonBasis,
      timezone: agent.timezone || priorityCall.timezone || SOURCE_TIMEZONE,
      market_calendar: marketCalendar,
      source_run_id: chooseSourceRunId(agent),
      validity_note: agent.validity_note || priorityCall.validity_note || "Operational freshness uses a provisional refresh expectation only. Forecast expiry is explicit and separate from the provisional refresh threshold.",
      horizon_note: agent.horizon_note || priorityCall.horizon_note || (assetUsesWeekdayActiveExpiry(agent.agent) ? DEFAULT_HORIZON_NOTE : ""),
      ...scheduleMeta
    };
  }

  function requiresExplicitForecastExpiry(agent = {}, timing = {}, priorityCall = {}) {
    const horizonCode = String(timing.horizon_code || priorityCall.horizon_code || "").toUpperCase();
    const statusAtBuild = String(timing.status_at_build || priorityCall.status_at_build || "").toUpperCase();
    const direction = priorityCall.direction;
    return horizonCode === "24H"
      && timing.horizon_duration === DEFAULT_HORIZON_DURATION
      && !isPendingDirection(direction)
      && !isExplicitNoCallDirection(direction)
      && !["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(statusAtBuild);
  }

  function assertValidExplicitLayer1Expiry(agent = {}, timing = {}, priorityCall = {}) {
    if (!requiresExplicitForecastExpiry(agent, timing, priorityCall)) {
      return;
    }

    const forecastWindowEnd = parseIso(timing.forecast_window_end);
    if (!forecastWindowEnd) {
      throw new Error(
        `Unable to derive explicit 24H forecast expiry for ${agent.agent || "UNKNOWN"} `
        + `(valid_from=${timing.valid_from || "null"}, sealed_at=${timing.sealed_at || "null"}, `
        + `forecast_window_end=${timing.forecast_window_end ?? "null"})`
      );
    }

    if (timing.expires_at !== timing.forecast_window_end) {
      throw new Error(
        `Explicit 24H expiry mismatch for ${agent.agent || "UNKNOWN"} `
        + `(forecast_window_end=${timing.forecast_window_end ?? "null"}, expires_at=${timing.expires_at ?? "null"})`
      );
    }
  }

  function resolveLayer1DisplayStatus(agent = {}, dashboardMeta = {}, nowValue = new Date()) {
    const timing = buildLayer1Timing(agent, dashboardMeta);
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const now = parseIso(nowValue) || new Date();
    const refreshDueAt = parseIso(timing.refresh_due_at);
    const forecastWindowEnd = parseIso(timing.forecast_window_end);

    if (!timing.sealed_at || isPendingDirection(priorityCall.direction)) return "UNAVAILABLE";
    if (timing.status_at_build === "SUPERSEDED") return "SUPERSEDED";
    if (timing.status_at_build === "UNAVAILABLE") return "UNAVAILABLE";

    if (isWeekendBlockedAsset(agent.agent) && isWeekendInTimeZone(now, SOURCE_TIMEZONE) && isExplicitNoCallDirection(priorityCall.direction)) {
      return "MARKET_CLOSED";
    }

    if (isExplicitNoCallDirection(priorityCall.direction)) return "NO_CALL";
    if (forecastWindowEnd && now.getTime() >= forecastWindowEnd.getTime()) return "EXPIRED";
    if (refreshDueAt && now.getTime() >= refreshDueAt.getTime()) return "STALE";
    return "ACTIVE";
  }

  function buildLayer2Timing({ pairCode, pairLabel, targetLeg, usdLeg, nowValue = new Date() }) {
    const targetAgent = targetLeg?.agent || null;
    const usdAgent = usdLeg?.agent || null;
    const now = parseIso(nowValue) || new Date();
    const targetStatus = targetAgent ? resolveLayer1DisplayStatus(targetAgent, targetLeg.dashboardMeta, now) : "UNAVAILABLE";
    const usdStatus = usdAgent ? resolveLayer1DisplayStatus(usdAgent, usdLeg.dashboardMeta, now) : "UNAVAILABLE";
    const targetTiming = targetAgent ? buildLayer1Timing(targetAgent, targetLeg.dashboardMeta) : {};
    const usdTiming = usdAgent ? buildLayer1Timing(usdAgent, usdLeg.dashboardMeta) : {};

    const targetValidFrom = parseIso(targetTiming.valid_from);
    const usdValidFrom = parseIso(usdTiming.valid_from);
    const targetRefreshDueAt = parseIso(targetTiming.refresh_due_at);
    const usdRefreshDueAt = parseIso(usdTiming.refresh_due_at);
    const targetForecastEnd = parseIso(targetTiming.forecast_window_end);
    const usdForecastEnd = parseIso(usdTiming.forecast_window_end);

    const pairValidFrom = targetValidFrom && usdValidFrom
      ? new Date(Math.max(targetValidFrom.getTime(), usdValidFrom.getTime())).toISOString()
      : (targetValidFrom || usdValidFrom)?.toISOString() || null;
    const pairRefreshDueAt = targetRefreshDueAt && usdRefreshDueAt
      ? new Date(Math.min(targetRefreshDueAt.getTime(), usdRefreshDueAt.getTime())).toISOString()
      : (targetRefreshDueAt || usdRefreshDueAt)?.toISOString() || null;
    const pairForecastEnd = targetForecastEnd && usdForecastEnd
      ? new Date(Math.min(targetForecastEnd.getTime(), usdForecastEnd.getTime())).toISOString()
      : null;
    const pairStartDate = parseIso(pairValidFrom);
    const pairEndDate = parseIso(pairForecastEnd);
    const forecastWindowsOverlap = Boolean(pairStartDate && pairEndDate && pairStartDate.getTime() < pairEndDate.getTime());

    let effectiveStatus = "ACTIVE";
    let statusAtBuild = "ACTIVE";
    let reason = null;

    if (!targetAgent || !usdAgent) {
      effectiveStatus = "UNAVAILABLE";
      statusAtBuild = "UNAVAILABLE";
      reason = "Missing supporting Layer 1 leg";
    } else if (!forecastWindowsOverlap) {
      effectiveStatus = "UNAVAILABLE";
      statusAtBuild = "UNAVAILABLE";
      reason = "Supporting Layer 1 forecast windows do not overlap";
    } else if (["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(targetStatus) || ["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(usdStatus)) {
      effectiveStatus = "UNAVAILABLE";
      statusAtBuild = "UNAVAILABLE";
    } else if (targetStatus === "NO_CALL" || usdStatus === "NO_CALL") {
      effectiveStatus = "NO_CALL";
      statusAtBuild = "NO_CALL";
    } else if ((targetForecastEnd && now.getTime() >= targetForecastEnd.getTime()) || (usdForecastEnd && now.getTime() >= usdForecastEnd.getTime()) || (pairEndDate && now.getTime() >= pairEndDate.getTime())) {
      effectiveStatus = "EXPIRED";
      statusAtBuild = "ACTIVE";
    } else if (targetStatus === "STALE" || usdStatus === "STALE") {
      effectiveStatus = "STALE";
      statusAtBuild = "ACTIVE";
    }

    return {
      pair_code: pairCode || null,
      pair_label: pairLabel || null,
      valid_from: effectiveStatus === "UNAVAILABLE" && reason ? null : pairValidFrom,
      refresh_due_at: effectiveStatus === "UNAVAILABLE" && reason ? null : pairRefreshDueAt,
      forecast_window_end: effectiveStatus === "UNAVAILABLE" && reason ? null : pairForecastEnd,
      expires_at: effectiveStatus === "UNAVAILABLE" && reason ? null : pairForecastEnd,
      status_at_build: statusAtBuild,
      effective_status: effectiveStatus,
      status_resolved_at: now.toISOString(),
      timezone: SOURCE_TIMEZONE,
      horizon_code: "24H",
      horizon_duration: DEFAULT_HORIZON_DURATION,
      horizon_basis: "PAIR_SUPPORTING_FORECAST_INTERSECTION_V1",
      market_calendar: `${targetTiming.market_calendar || assetMarketCalendar(targetAgent?.agent)}__${usdTiming.market_calendar || assetMarketCalendar(usdAgent?.agent)}`,
      reason,
      supporting_legs: {
        target: {
          asset: targetLeg.agent?.agent || null,
          effective_status: targetStatus,
          valid_from: targetTiming.valid_from || null,
          refresh_due_at: targetTiming.refresh_due_at || null,
          forecast_window_end: targetTiming.forecast_window_end || null,
          expires_at: targetTiming.expires_at || null,
          sealed_at: targetTiming.sealed_at || null,
          source_run_id: targetTiming.source_run_id || null
        },
        usd: {
          asset: usdLeg.agent?.agent || null,
          effective_status: usdStatus,
          valid_from: usdTiming.valid_from || null,
          refresh_due_at: usdTiming.refresh_due_at || null,
          forecast_window_end: usdTiming.forecast_window_end || null,
          expires_at: usdTiming.expires_at || null,
          sealed_at: usdTiming.sealed_at || null,
          source_run_id: usdTiming.source_run_id || null
        }
      }
    };
  }

  function resolveLayer2DisplayStatus(pair = {}, nowValue = new Date()) {
    const storedStatus = String(pair.effective_status || pair.status_at_build || "UNAVAILABLE").toUpperCase();
    const now = parseIso(nowValue) || new Date();
    const refreshDueAt = parseIso(pair.refresh_due_at);
    const forecastWindowEnd = parseIso(pair.forecast_window_end || pair.expires_at);

    if (storedStatus === "UNAVAILABLE" || storedStatus === "MARKET_CLOSED" || storedStatus === "SUPERSEDED") return "UNAVAILABLE";
    if (storedStatus === "NO_CALL") return "NO_CALL";
    if (forecastWindowEnd && now.getTime() >= forecastWindowEnd.getTime()) return "EXPIRED";
    if (storedStatus === "STALE" || (refreshDueAt && now.getTime() >= refreshDueAt.getTime())) return "STALE";
    return "ACTIVE";
  }

  function formatDisplayTime(value, timeZone = DISPLAY_TIMEZONE) {
    const date = parseIso(value);
    if (!date) return "Pending";
    return new Intl.DateTimeFormat("en-GB", {
      timeZone,
      day: "2-digit",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }).format(date);
  }

  function formatRemainingDuration(targetValue, nowValue = new Date()) {
    const target = parseIso(targetValue);
    const now = parseIso(nowValue) || new Date();
    if (!target) return null;

    const diffMs = target.getTime() - now.getTime();
    if (diffMs <= 0) return null;

    const totalMinutes = Math.ceil(diffMs / 60000);
    const days = Math.floor(totalMinutes / 1440);
    const hours = Math.floor((totalMinutes % 1440) / 60);
    const minutes = totalMinutes % 60;
    const parts = [];

    if (days > 0) parts.push(`${days}d`);
    if (hours > 0) parts.push(`${hours}h`);
    if ((minutes > 0 || parts.length === 0) && parts.length < 2) parts.push(`${minutes}m`);

    return parts.join(" ");
  }

  function formatTimeUntilRefresh(refreshDueAtValue, nowValue = new Date()) {
    const remaining = formatRemainingDuration(refreshDueAtValue, nowValue);
    if (!parseIso(refreshDueAtValue)) return "Awaiting refresh schedule";
    if (!remaining) return "refresh overdue";
    return `refresh due in ${remaining}`;
  }

  function formatTimeUntilForecastExpiry(forecastWindowEndValue, nowValue = new Date()) {
    const forecastWindowEnd = parseIso(forecastWindowEndValue);
    if (!forecastWindowEnd) return "Awaiting forecast expiry";
    const remaining = formatRemainingDuration(forecastWindowEnd, nowValue);
    if (!remaining) return "expired";
    return `expires in ${remaining}`;
  }

  function enrichLayer1DashboardData(data = {}) {
    const dashboardMeta = data.dashboard_meta || {};
    const scheduleMeta = provisionalScheduleMetadata(dashboardMeta);
    const nowIso = new Date().toISOString();
    const agents = (data.agents || []).map((rawAgent) => {
      const timing = buildLayer1Timing(rawAgent, dashboardMeta);
      const effectiveStatus = resolveLayer1DisplayStatus(rawAgent, dashboardMeta, new Date());
      assertValidExplicitLayer1Expiry(rawAgent, timing, rawAgent.priority_call || rawAgent.calls?.["24h"] || {});
      const calls = { ...(rawAgent.calls || {}) };
      const call24 = { ...(calls["24h"] || {}) };
      call24.generated_at = call24.generated_at || timing.generated_at;
