  const isExplicitNoCallDirection = sharedValidity.isExplicitNoCallDirection || ((direction = "") => {
    const normalized = String(direction || "").trim().toUpperCase();
    return normalized === "NO CALL" || normalized === "NO 24H CALL";
  });
  const PAIRS = [
    { pair: "EUR/USD", pair_code: "EUR_USD", target_asset: "EUR" },
    { pair: "XAU/USD", pair_code: "XAU_USD", target_asset: "GOLD" },
    { pair: "BTC/USD", pair_code: "BTC_USD", target_asset: "BTC" },
    { pair: "NQ/USD", pair_code: "NQ_USD", target_asset: "NQ" }
  ];

  function numberOrNull(value) {
    if (value === null || value === undefined || value === "") return null;
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : null;
  }

  function asArray(value) {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined) return [];
    return [value];
  }

  function parseMaybeJson(value, fallback = {}) {
    if (value === null || value === undefined || value === "") return fallback;
    if (typeof value === "object") return value;
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === "object" ? parsed : fallback;
    } catch (error) {
      return fallback;
    }
  }

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  function parseIso(value) {
    if (!value) return null;
    const date = value instanceof Date ? value : new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  function timestampMs(value) {
    const parsed = parseIso(value);
    return parsed ? parsed.getTime() : 0;
  }

  function parseExecutionClockLabel(label = DEFAULT_EXECUTION_CLOCK) {
    const match = String(label || "").match(/(\d{1,2}):(\d{2})\s*ET/i);
    return {
      hour: match ? Number(match[1]) : 7,
      minute: match ? Number(match[2]) : 0
    };
  }

  function getZonedParts(date, timeZone) {
    const formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false
    });
    const lookup = Object.fromEntries(formatter.formatToParts(date).map((part) => [part.type, part.value]));
    return {
      year: Number(lookup.year),
      month: Number(lookup.month),
      day: Number(lookup.day),
      hour: Number(lookup.hour),
      minute: Number(lookup.minute),
      second: Number(lookup.second)
    };
  }

  function parseOffsetMinutes(offsetLabel) {
    const match = String(offsetLabel || "").match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/i);
    if (!match) return 0;
    const sign = match[1] === "-" ? -1 : 1;
    const hours = Number(match[2] || 0);
    const minutes = Number(match[3] || 0);
    return sign * ((hours * 60) + minutes);
  }

  function getOffsetMinutes(date, timeZone) {
    const formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hour: "2-digit",
      minute: "2-digit",
      timeZoneName: "shortOffset",
      hour12: false
    });
    const offsetPart = formatter.formatToParts(date).find((part) => part.type === "timeZoneName");
    return parseOffsetMinutes(offsetPart?.value || "GMT+0");
  }

  function zonedDateTimeToUtc(parts, timeZone) {
    let utcMs = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second || 0, 0);

    for (let i = 0; i < 4; i += 1) {
      const offsetMinutes = getOffsetMinutes(new Date(utcMs), timeZone);
      const adjustedUtcMs = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second || 0, 0) - (offsetMinutes * 60000);
      if (adjustedUtcMs === utcMs) break;
      utcMs = adjustedUtcMs;
    }

    return new Date(utcMs);
  }

  function addZonedDays(parts, days) {
    const utcDate = new Date(Date.UTC(parts.year, parts.month - 1, parts.day));
    utcDate.setUTCDate(utcDate.getUTCDate() + days);
    return {
      year: utcDate.getUTCFullYear(),
      month: utcDate.getUTCMonth() + 1,
      day: utcDate.getUTCDate()
    };
  }

  function computeNextRefreshDueAt(sealedAtValue, executionClockLabel = DEFAULT_EXECUTION_CLOCK, timeZone = SOURCE_TIMEZONE) {
    const sealedAt = parseIso(sealedAtValue);
    if (!sealedAt) return null;

    const executionClock = parseExecutionClockLabel(executionClockLabel);
    const sealedParts = getZonedParts(sealedAt, timeZone);
    let dueParts = {
      year: sealedParts.year,
      month: sealedParts.month,
      day: sealedParts.day,
      hour: executionClock.hour,
      minute: executionClock.minute,
      second: 0
    };
    let dueAt = zonedDateTimeToUtc(dueParts, timeZone);

    if (dueAt.getTime() <= sealedAt.getTime()) {
      const nextDay = addZonedDays(sealedParts, 1);
      dueParts = {
        ...nextDay,
        hour: executionClock.hour,
        minute: executionClock.minute,
        second: 0
      };
      dueAt = zonedDateTimeToUtc(dueParts, timeZone);
    }

    return dueAt.toISOString();
  }

  function isWeekendBlockedAsset(asset = "") {
    return WEEKEND_BLOCKED_ASSETS.has(String(asset || "").toUpperCase());
  }

  function isWeekendInLondon(nowValue = new Date()) {
    const now = parseIso(nowValue) || new Date();
    const weekday = now.toLocaleDateString("en-US", {
      timeZone: DISPLAY_TIMEZONE,
      weekday: "long"
    });
    return weekday === "Saturday" || weekday === "Sunday";
  }

  function normalizeDirectionalSignalKey(value = "") {
    const normalized = String(value || "").trim().toUpperCase();
    if (normalized === "BULLISH" || normalized === "BEARISH") return normalized;
    return null;
  }

  function confidenceBucketFromValue(confidence) {
    const numeric = numberOrNull(confidence);
    if (numeric === null) return null;
    if (numeric >= 80) return { key: "VERY_STRONG", label: "Very Strong" };
    if (numeric >= 65) return { key: "STRONG", label: "Strong" };
    if (numeric >= 50) return { key: "MODERATE", label: "Moderate" };
    if (numeric >= 0) return { key: "WEAK", label: "Weak" };
    return null;
  }

  function extractWarningText(warnings) {
    return asArray(warnings)
      .map((warning) => {
        if (warning === null || warning === undefined) return "";
        if (typeof warning === "string") return warning;
        if (typeof warning === "object") {
          return [
            warning.label,
            warning.code,
            warning.message,
            warning.reason,
            warning.text
          ].filter(Boolean).join(" ");
        }
        return String(warning);
      })
      .join(" ")
      .toLowerCase();
  }

  function computeHeadlineConfidenceData(input = {}) {
    const bullCase = numberOrNull(input.bullCase);
    const bearCase = numberOrNull(input.bearCase);
    const participation = numberOrNull(input.participation);
    const netEdge = numberOrNull(input.netEdge);
    const direction = input.direction || "PENDING";
    const fallbackConfidence = numberOrNull(input.fallbackConfidence);
    const explicitStrength = input.strengthOverride || null;
    const missingCount = Number.isFinite(Number(input.missingInputsCount))
      ? Number(input.missingInputsCount)
      : asArray(input.missingInputs).filter(Boolean).length;

    function deriveConfidenceStrength(confidence) {
      if (direction === "NO_CALL" || direction === "NO 24H CALL") return "NO_CALL";
      if (confidence === null || confidence === undefined) return "PENDING";
      const edge = Math.abs(Number(netEdge) || 0);
      const active = Number(participation) || 0;
      if (confidence >= 80 && edge >= 25 && active >= 50) return "VERY_STRONG";
      if (confidence >= 65 && edge >= 18 && active >= 35) return "STRONG";
      if (confidence >= 50 && edge >= 10 && active >= 25) return "MODERATE";
      if (confidence > 0) return "WEAK";
      return "NO_CALL";
    }

    if ([bullCase, bearCase, participation, netEdge].some((value) => value === null)) {
      const fallbackValue = Number.isFinite(fallbackConfidence) ? fallbackConfidence : null;
      return {
        value: fallbackValue,
        strength: explicitStrength || deriveConfidenceStrength(fallbackValue)
      };
    }

    let confidence =
      ((Math.max(bullCase, bearCase) / 100) * 0.45) +
      ((participation / 100) * 0.35) +
      ((Math.abs(netEdge) / 100) * 0.20);

    if (participation < 40) confidence -= 0.10;
    if (participation < 25) confidence -= 0.20;
    if (Math.abs(netEdge) < 20) confidence -= 0.10;
    if (missingCount >= 3) confidence -= 0.05;
    if (missingCount >= 6) confidence -= 0.10;

    const warningText = extractWarningText(input.warnings);
    const weeklyStatus = String(input.weeklyCandleStatus || "").toLowerCase();

    if (warningText.includes("event risk") || warningText.includes("high impact event") || warningText.includes("tier 1 event")) confidence -= 0.10;
    if (weeklyStatus === "consolidating" || warningText.includes("weekly consolidation")) confidence -= 0.05;
    if (warningText.includes("conviction audit") || warningText.includes("audit flag") || warningText.includes("audit warning")) confidence -= 0.05;
    if (warningText.includes("o layer")) confidence -= 0.05;
    if (warningText.includes("adr warning") || warningText.includes("session warning")) confidence -= 0.05;

    const finalConfidence = Math.round(clamp(confidence, 0, 1) * 100);
    return {
      value: finalConfidence,
      strength: explicitStrength || deriveConfidenceStrength(finalConfidence)
    };
  }

  function deriveLayer2PairSignal(input = {}) {
    const instrument = input.instrument || input.pair || "Pair";
    const targetDirection = normalizeDirectionalSignalKey(input.targetDirection);
    const usdDirection = normalizeDirectionalSignalKey(input.usdDirection);
    const targetConfidence = numberOrNull(input.targetConfidence);
    const usdConfidence = numberOrNull(input.usdConfidence);

    let reasonKey = null;
    let reason = "";

    if (!targetDirection) {
      reasonKey = "unsupported_target_direction";
      reason = "Target 24H signal is non-directional, so there is no Layer 2 pair trade.";
    } else if (!usdDirection) {
      reasonKey = "unsupported_usd_direction";
      reason = "USD 24H signal is non-directional, so there is no Layer 2 pair trade.";
    } else if (targetConfidence === null || usdConfidence === null) {
      reasonKey = "missing_combined_confidence";
      reason = "Missing Layer 1 headline confidence prevents a Layer 2 pair trade.";
    } else if (targetDirection === usdDirection) {
      reasonKey = "same_direction_conflict";
      reason = "Both assets point in the same 24H direction, so there is no clear relative edge.";
    }

    if (reasonKey) {
      return {
        instrument,
        tradable: false,
        direction: "NO TRADE",
        combinedConfidence: null,
        strengthBucket: null,
        strengthBucketKey: null,
        reasonKey,
        reason
      };
    }

    const combinedConfidence = Math.min(targetConfidence, usdConfidence);
    const bucket = confidenceBucketFromValue(combinedConfidence);
    return {
      instrument,
      tradable: true,
      direction: targetDirection === "BULLISH" && usdDirection === "BEARISH" ? "BUY" : "SELL",
      combinedConfidence,
      strengthBucket: bucket ? bucket.label : null,
      strengthBucketKey: bucket ? bucket.key : null,
      reasonKey: "tradable_pair",
      reason: `${instrument} is tradable because the target and USD 24H signals are opposite. Combined confidence is the lower Layer 1 confidence.`
    };
  }

  function baseDashboardMeta(dashboardMeta = {}) {
    return {
      execution_clock: dashboardMeta.execution_clock || DEFAULT_EXECUTION_CLOCK,
      validity_contract_version: dashboardMeta.validity_contract_version === DEFAULT_VALIDITY_CONTRACT_VERSION
        ? dashboardMeta.validity_contract_version
        : DEFAULT_VALIDITY_CONTRACT_VERSION
    };
  }

  function buildLayer1Timing(agent = {}, dashboardMeta = {}) {
    if (typeof buildSharedLayer1Timing === "function") {
      return buildSharedLayer1Timing(agent, dashboardMeta);
    }

    const meta = baseDashboardMeta(dashboardMeta);
    const sealedAt = agent.sealed_at || agent.full_output?.created_at || agent.last_run_et || agent.created_at || null;
    const generatedAt = agent.generated_at || agent.last_run_et || sealedAt;
    const validFrom = agent.valid_from || sealedAt;
    const refreshDueAt = agent.refresh_due_at || computeNextRefreshDueAt(validFrom || sealedAt, meta.execution_clock, SOURCE_TIMEZONE);
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const statusAtBuild = String(agent.status_at_build || priorityCall.status_at_build || "").toUpperCase() || "ACTIVE";
    return {
      generated_at: generatedAt,
      sealed_at: sealedAt,
      valid_from: validFrom,
      refresh_due_at: refreshDueAt,
      forecast_window_end: Object.prototype.hasOwnProperty.call(agent, "forecast_window_end") ? agent.forecast_window_end : null,
      expires_at: Object.prototype.hasOwnProperty.call(agent, "expires_at") ? agent.expires_at : null,
      status_at_build: statusAtBuild,
      effective_status: String(agent.effective_status || priorityCall.effective_status || statusAtBuild).toUpperCase(),
      status_resolved_at: agent.status_resolved_at || priorityCall.status_resolved_at || null,
      horizon_code: agent.horizon_code || priorityCall.horizon_code || "24H",
      horizon_duration: agent.horizon_duration || priorityCall.horizon_duration || "PT24H",
      horizon_basis: agent.horizon_basis || priorityCall.horizon_basis || "AMBIGUOUS_LIVE_24H",
      timezone: agent.timezone || priorityCall.timezone || SOURCE_TIMEZONE,
      market_calendar: agent.market_calendar || priorityCall.market_calendar || null,
      source_run_id: agent.source_run_id || agent.full_output?.source_run_id || agent.full_output?.execution_id || agent.full_output?.workflow_execution_id || null
    };
  }

  function resolveLayer1DisplayStatus(agent = {}, dashboardMeta = {}, nowValue = new Date()) {
    if (typeof resolveSharedLayer1DisplayStatus === "function") {
      return resolveSharedLayer1DisplayStatus(agent, dashboardMeta, nowValue);
    }

    const timing = buildLayer1Timing(agent, dashboardMeta);
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const refreshDueAt = parseIso(timing.refresh_due_at);
    const now = parseIso(nowValue) || new Date();

    if (!timing.sealed_at) return "UNAVAILABLE";
    if (timing.status_at_build === "SUPERSEDED") return "SUPERSEDED";
    if (isWeekendBlockedAsset(agent.agent) && isWeekendInLondon(now) && isExplicitNoCallDirection(priorityCall.direction)) return "MARKET_CLOSED";
    if (timing.status_at_build === "UNAVAILABLE") return "UNAVAILABLE";
    if (timing.status_at_build === "NO_CALL" || isExplicitNoCallDirection(priorityCall.direction)) return "NO_CALL";
    if (refreshDueAt && now.getTime() >= refreshDueAt.getTime()) return "STALE";
    return "ACTIVE";
  }

  function buildLayer2Timing(targetAgent, usdAgent, dashboardMeta = {}, nowValue = new Date(), pair = "") {
    if (typeof buildSharedLayer2Timing === "function") {
      return buildSharedLayer2Timing({
        pairCode: pair ? pair.replace("/", "_") : null,
        pairLabel: pair,
        targetLeg: { agent: targetAgent, dashboardMeta },
        usdLeg: { agent: usdAgent, dashboardMeta },
        nowValue
      });
    }

    const targetStatus = targetAgent ? resolveLayer1DisplayStatus(targetAgent, dashboardMeta, nowValue) : "UNAVAILABLE";
    const usdStatus = usdAgent ? resolveLayer1DisplayStatus(usdAgent, dashboardMeta, nowValue) : "UNAVAILABLE";
    const targetTiming = targetAgent ? buildLayer1Timing(targetAgent, dashboardMeta) : {};
    const usdTiming = usdAgent ? buildLayer1Timing(usdAgent, dashboardMeta) : {};
    const now = parseIso(nowValue) || new Date();

    const targetValidFrom = parseIso(targetTiming.valid_from);
    const usdValidFrom = parseIso(usdTiming.valid_from);
    const targetRefreshDueAt = parseIso(targetTiming.refresh_due_at);
    const usdRefreshDueAt = parseIso(usdTiming.refresh_due_at);
    const validFrom = targetValidFrom && usdValidFrom
      ? (targetValidFrom.getTime() >= usdValidFrom.getTime() ? targetValidFrom.toISOString() : usdValidFrom.toISOString())
      : null;
    const refreshDueAt = targetRefreshDueAt && usdRefreshDueAt
      ? (targetRefreshDueAt.getTime() <= usdRefreshDueAt.getTime() ? targetRefreshDueAt.toISOString() : usdRefreshDueAt.toISOString())
      : null;
    const windowsOverlap = Boolean(targetValidFrom && usdValidFrom && targetRefreshDueAt && usdRefreshDueAt && targetValidFrom.getTime() < usdRefreshDueAt.getTime() && usdValidFrom.getTime() < targetRefreshDueAt.getTime());

    let effectiveStatus = "ACTIVE";
    let reason = null;

    if (!targetAgent || !usdAgent) {
      effectiveStatus = "UNAVAILABLE";
      reason = "Missing supporting Layer 1 leg";
    } else if (!windowsOverlap) {
      effectiveStatus = "UNAVAILABLE";
      reason = "Supporting Layer 1 validity windows do not overlap";
    } else if (["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(targetStatus) || ["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(usdStatus)) {
      effectiveStatus = "UNAVAILABLE";
    } else if (targetStatus === "NO_CALL" || usdStatus === "NO_CALL") {
      effectiveStatus = "NO_CALL";
    } else if (targetStatus === "STALE" || usdStatus === "STALE" || (refreshDueAt && now.getTime() >= parseIso(refreshDueAt).getTime())) {
      effectiveStatus = "STALE";
    }

    return {
      pair,
      valid_from: effectiveStatus === "UNAVAILABLE" && reason ? null : validFrom,
      refresh_due_at: effectiveStatus === "UNAVAILABLE" && reason ? null : refreshDueAt,
      forecast_window_end: null,
      expires_at: null,
      status_at_build: effectiveStatus,
      effective_status: effectiveStatus,
      status_resolved_at: now.toISOString(),
      timezone: SOURCE_TIMEZONE,
      reason,
      target_status: targetStatus,
      usd_status: usdStatus,
      target_valid_from: targetTiming.valid_from || null,
      target_refresh_due_at: targetTiming.refresh_due_at || null,
      target_forecast_window_end: targetTiming.forecast_window_end || null,
      target_source_run_id: targetTiming.source_run_id || null,
      target_sealed_at: targetTiming.sealed_at || null,
      usd_valid_from: usdTiming.valid_from || null,
      usd_refresh_due_at: usdTiming.refresh_due_at || null,
      usd_forecast_window_end: usdTiming.forecast_window_end || null,
      usd_source_run_id: usdTiming.source_run_id || null,
      usd_sealed_at: usdTiming.sealed_at || null
    };
  }

  function computeAgentHeadlineConfidence(agent = {}) {
    const call = agent.priority_call || agent.calls?.["24h"] || {};
    const model = call.conviction_model || agent.timeframe_models?.["24h"]?.conviction_model || {};
    const timeframeModel = agent.timeframe_models?.["24h"] || {};
    const data = computeHeadlineConfidenceData({
      bullCase: model.bullish_argument_pct,
      bearCase: model.bearish_argument_pct,
      participation: model.directional_participation_pct ?? model.active_participation_pct ?? model.participation,
      netEdge: model.net_edge_pct,
      direction: call.direction || "PENDING",
      warnings: [
        ...asArray(agent.warnings),
        ...asArray(call.warnings),
        ...asArray(agent.full_output?.risk_flags),
        ...asArray(agent.full_output?.warnings),
        ...asArray(timeframeModel.risk_flags),
        ...asArray(timeframeModel.warnings)
      ],
      missingInputs: timeframeModel.missing_inputs || model.missing_inputs || [],
      missingInputsCount: timeframeModel.missing_inputs_count ?? model.missing_inputs_count ?? null,
      weeklyCandleStatus: timeframeModel.weekly_candle_status ?? model.weekly_candle_status ?? "",
      fallbackConfidence: model.final_confidence ?? call.confidence ?? call.conviction ?? null,
      strengthOverride: model.confidence_strength || null
    });
    return data.value;
  }

  function normaliseAgent(agent = {}, dashboardMeta = {}, nowValue = new Date()) {
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const timing = buildLayer1Timing(agent, dashboardMeta);
    return {
      agent: agent.agent || null,
      raw_direction: priorityCall.direction || "PENDING",
      strict_direction: normalizeDirectionalSignalKey(priorityCall.direction),
      headline_confidence: computeAgentHeadlineConfidence(agent),
      status: resolveLayer1DisplayStatus(agent, dashboardMeta, nowValue),
      valid_from: timing.valid_from,
      refresh_due_at: timing.refresh_due_at,
      forecast_window_end: timing.forecast_window_end,
      expires_at: timing.expires_at,
      source_run_id: timing.source_run_id,
      sealed_at: timing.sealed_at,
      generated_at: timing.generated_at,
      reason: priorityCall.reason || agent.reasoning_summary || "",
      record: agent
    };
  }

  function rowToAgent(row = {}) {
    const output = parseMaybeJson(row.full_output, parseMaybeJson(row.raw_agent_output, {}));
    const timeframeModel = output.timeframe_models?.["24h"] || {};
    const convictionModel = timeframeModel.conviction_model || output.conviction_model || {};
    const call24 = {
      direction: row.call_24h_direction || row.direction_24h || output.direction_24h || output.today_call?.direction || "PENDING",
      conviction: numberOrNull(row.call_24h_conviction ?? row.conviction_24h ?? output.conviction_24h ?? output.today_call?.confidence ?? null),
      reason: row.call_24h_reason || output.reason_24h || output.today_call?.executive_summary || row.reasoning_summary || output.reasoning_summary || "",
      conviction_model: convictionModel,
      warnings: [
        ...asArray(timeframeModel.warnings),
        ...asArray(timeframeModel.risk_flags)
      ]
    };

    return {
      agent: row.agent_name || null,
      last_run_et: row.run_time_et || row.created_at || null,
      generated_at: row.run_time_et || row.created_at || null,
      sealed_at: row.created_at || output.created_at || row.run_time_et || null,
      valid_from: row.valid_from || output.valid_from || row.created_at || output.created_at || row.run_time_et || null,
      refresh_due_at: row.refresh_due_at || output.refresh_due_at || null,
      status_at_build: row.status_at_build || output.status_at_build || "ACTIVE",
      effective_status: row.effective_status || output.effective_status || row.status_at_build || output.status_at_build || "ACTIVE",
      status_resolved_at: row.status_resolved_at || output.status_resolved_at || null,
      forecast_window_end: Object.prototype.hasOwnProperty.call(row, "forecast_window_end")
        ? row.forecast_window_end
        : Object.prototype.hasOwnProperty.call(output, "forecast_window_end")
          ? output.forecast_window_end
          : null,
      expires_at: Object.prototype.hasOwnProperty.call(row, "expires_at")
        ? row.expires_at
        : Object.prototype.hasOwnProperty.call(output, "expires_at")
          ? output.expires_at
          : null,
      horizon_code: row.horizon_code || output.horizon_code || "24H",
      horizon_duration: row.horizon_duration || output.horizon_duration || "PT24H",
      horizon_basis: row.horizon_basis || output.horizon_basis || "AMBIGUOUS_LIVE_24H",
      timezone: row.timezone || output.timezone || SOURCE_TIMEZONE,
      market_calendar: row.market_calendar || output.market_calendar || null,
      full_output: output,
      warnings: [
        ...asArray(row.warnings),
        ...asArray(output.risk_flags),
        ...asArray(output.warnings)
      ],
      timeframe_models: output.timeframe_models || {},
      priority_call: call24,
      calls: { "24h": call24 },
      reasoning_summary: row.reasoning_summary || output.reasoning_summary || "",
      source_run_id: row.source_run_id || output.source_run_id || output.execution_id || output.workflow_execution_id || null
    };
  }

  function sortRowsNewestFirst(rows = []) {
    return rows
      .slice()
      .sort((a, b) => timestampMs(b.created_at || b.run_time_et) - timestampMs(a.created_at || a.run_time_et));
  }

  function windowsOverlap(targetTiming = {}, usdTiming = {}) {
    const targetValidFrom = parseIso(targetTiming.valid_from);
    const usdValidFrom = parseIso(usdTiming.valid_from);
    const targetRefreshDueAt = parseIso(targetTiming.refresh_due_at);
    const usdRefreshDueAt = parseIso(usdTiming.refresh_due_at);
    return Boolean(
      targetValidFrom
      && usdValidFrom
      && targetRefreshDueAt
      && usdRefreshDueAt
      && targetValidFrom.getTime() < usdRefreshDueAt.getTime()
      && usdValidFrom.getTime() < targetRefreshDueAt.getTime()
    );
  }

  function rankRowPair(candidate) {
    const targetMs = timestampMs(candidate.targetRow?.created_at || candidate.targetRow?.run_time_et);
    const usdMs = timestampMs(candidate.usdRow?.created_at || candidate.usdRow?.run_time_et);
    return {
      latest: Math.max(targetMs, usdMs),
      earliest: Math.min(targetMs, usdMs)
    };
  }

  function compareRowPairsNewestFirst(a, b) {
    const aRank = rankRowPair(a);
    const bRank = rankRowPair(b);
    if (bRank.latest !== aRank.latest) return bRank.latest - aRank.latest;
    if (bRank.earliest !== aRank.earliest) return bRank.earliest - aRank.earliest;
    return 0;
  }

  function candidateRowInfo(row, dashboardMeta = {}, buildNow = new Date()) {
    if (!row) return null;
    const agent = rowToAgent(row);
    const timing = buildLayer1Timing(agent, dashboardMeta);
    return {
      row,
      agent,
      timing,
      status: resolveLayer1DisplayStatus(agent, dashboardMeta, buildNow),
      sourceRunId: timing.source_run_id || null
    };
  }

  function latestRowForAsset(rows = [], asset = "") {
    return sortRowsNewestFirst(rows.filter((row) => row.agent_name === asset && Number(row.layer) === 1))[0] || null;
  }

  function selectPreferredPairRows(rows = [], config, dashboardMeta = {}, buildNow = new Date()) {
    const targetCandidates = sortRowsNewestFirst(rows.filter((row) => row.agent_name === config.target_asset && Number(row.layer) === 1))
      .map((row) => candidateRowInfo(row, dashboardMeta, buildNow));
    const usdCandidates = sortRowsNewestFirst(rows.filter((row) => row.agent_name === "USD" && Number(row.layer) === 1))
      .map((row) => candidateRowInfo(row, dashboardMeta, buildNow));

    if (!targetCandidates.length || !usdCandidates.length) {
      return {
        target: targetCandidates[0] || null,
        usd: usdCandidates[0] || null
      };
    }

    const sameRunPairs = [];
    const overlappingPairs = [];

    targetCandidates.forEach((target) => {
      usdCandidates.forEach((usd) => {
        const pair = { target, usd, targetRow: target.row, usdRow: usd.row };
        if (target.sourceRunId && usd.sourceRunId && target.sourceRunId === usd.sourceRunId) {
          sameRunPairs.push(pair);
        }
        if (windowsOverlap(target.timing, usd.timing)) {
          overlappingPairs.push(pair);
        }
      });
    });

    if (sameRunPairs.length) {
      sameRunPairs.sort(compareRowPairsNewestFirst);
      return {
        target: sameRunPairs[0].target,
        usd: sameRunPairs[0].usd
      };
    }

    if (overlappingPairs.length) {
      overlappingPairs.sort(compareRowPairsNewestFirst);
      return {
        target: overlappingPairs[0].target,
        usd: overlappingPairs[0].usd
      };
    }

    return {
      target: targetCandidates[0] || null,
      usd: usdCandidates[0] || null
    };
  }

  function resolvePairReason(pairSignal, timing) {
    if (timing.reason) return timing.reason;
    if (timing.effective_status === "NO_CALL") return pairSignal.reason || "One supporting Layer 1 leg is non-directional.";
    if (timing.effective_status === "STALE") return "One supporting Layer 1 leg is stale.";
    if (timing.effective_status === "EXPIRED") return "One supporting Layer 1 forecast has expired.";
    return pairSignal.reason;
  }

  function timingLeg(timing, side) {
    if (!timing || !timing.supporting_legs) return null;
    return timing.supporting_legs[side] || null;
  }

  function buildPairEntry(config, targetAgent, usdAgent, dashboardMeta = {}, buildNow = new Date()) {
    const buildNowIso = parseIso(buildNow)?.toISOString() || new Date().toISOString();
    const target = targetAgent ? normaliseAgent(targetAgent, dashboardMeta, buildNowIso) : null;
    const usd = usdAgent ? normaliseAgent(usdAgent, dashboardMeta, buildNowIso) : null;
    const pairSignal = deriveLayer2PairSignal({
      instrument: config.pair,
      targetDirection: target?.strict_direction,
      usdDirection: usd?.strict_direction,
      targetConfidence: target?.headline_confidence,
      usdConfidence: usd?.headline_confidence
    });
    const timing = buildLayer2Timing(targetAgent, usdAgent, dashboardMeta, buildNowIso, config.pair);
    const targetTiming = timingLeg(timing, "target");
    const usdTiming = timingLeg(timing, "usd");
    const callStatus = timing.effective_status === "UNAVAILABLE"
      ? "UNAVAILABLE"
      : pairSignal.tradable
        ? "TRADE"
        : "NO_CALL";

    return {
      pair: config.pair,
      pair_code: config.pair_code,
      direction: pairSignal.direction,
      decision: pairSignal.tradable ? "TRADE" : "NO_TRADE",
      combined_confidence: pairSignal.combinedConfidence,
      strength: pairSignal.strengthBucket,
      reason: resolvePairReason(pairSignal, timing),
      call_status: callStatus,
      effective_status: timing.effective_status,
      status_at_build: timing.status_at_build,
      status_resolved_at: buildNowIso,
      generated_at: buildNowIso,
      sealed_at: buildNowIso,
      valid_from: timing.valid_from,
      refresh_due_at: timing.refresh_due_at,
      forecast_window_end: timing.forecast_window_end,
      expires_at: timing.expires_at,
      horizon_code: timing.horizon_code || "24H",
      horizon_duration: timing.horizon_duration || "PT24H",
      horizon_basis: timing.horizon_basis || "PAIR_SUPPORTING_FORECAST_INTERSECTION_V1",
      timezone: timing.timezone || SOURCE_TIMEZONE,
      market_calendar: timing.market_calendar || null,
      target_asset: config.target_asset,
      target_direction: target?.raw_direction || "PENDING",
      target_confidence: target?.headline_confidence ?? null,
      target_status: timing.target_status || targetTiming?.effective_status || null,
      target_valid_from: timing.target_valid_from || targetTiming?.valid_from || null,
      target_refresh_due_at: timing.target_refresh_due_at || targetTiming?.refresh_due_at || null,
      target_forecast_window_end: timing.target_forecast_window_end || targetTiming?.forecast_window_end || null,
      target_source_run_id: timing.target_source_run_id || targetTiming?.source_run_id || null,
      target_sealed_at: timing.target_sealed_at || targetTiming?.sealed_at || null,
      usd_direction: usd?.raw_direction || "PENDING",
      usd_confidence: usd?.headline_confidence ?? null,
      usd_status: timing.usd_status || usdTiming?.effective_status || null,
      usd_valid_from: timing.usd_valid_from || usdTiming?.valid_from || null,
      usd_refresh_due_at: timing.usd_refresh_due_at || usdTiming?.refresh_due_at || null,
      usd_forecast_window_end: timing.usd_forecast_window_end || usdTiming?.forecast_window_end || null,
      usd_source_run_id: timing.usd_source_run_id || usdTiming?.source_run_id || null,
      usd_sealed_at: timing.usd_sealed_at || usdTiming?.sealed_at || null,
      source_run_id: (timing.target_source_run_id || targetTiming?.source_run_id) && (timing.target_source_run_id || targetTiming?.source_run_id) === (timing.usd_source_run_id || usdTiming?.source_run_id)
        ? (timing.target_source_run_id || targetTiming?.source_run_id)
        : null,
      logic_version: DEFAULT_LOGIC_VERSION,
      validity_contract_version: dashboardMeta.validity_contract_version || DEFAULT_VALIDITY_CONTRACT_VERSION
    };
  }

  function rankTradeOpportunities(pairs = []) {
    const tradable = pairs
      .filter((pair) => pair.decision === "TRADE")
      .slice()
      .sort((a, b) => {
        const confidenceDelta = Number(b.combined_confidence || 0) - Number(a.combined_confidence || 0);
        if (confidenceDelta !== 0) return confidenceDelta;
        return String(a.pair || "").localeCompare(String(b.pair || ""));
      });

    tradable.forEach((pair, index) => {
      pair.rank = index + 1;
    });

    return pairs;
  }

  function buildStoredLayer2DashboardFromAgents(layer1Data = {}, options = {}) {
    const dashboardMeta = baseDashboardMeta(layer1Data.dashboard_meta || {});
    const buildNow = options.buildNow || new Date().toISOString();
    const agents = new Map((layer1Data.agents || []).map((agent) => [agent.agent, agent]));
    const pairs = rankTradeOpportunities(
      PAIRS.map((config) => buildPairEntry(config, agents.get(config.target_asset) || null, agents.get("USD") || null, dashboardMeta, buildNow))
    );

    return {
      dashboard_meta: {
        last_updated_et: buildNow,
        source: "layer_2_trade_selection_agent",
        dashboard_source: DEFAULT_DASHBOARD_SOURCE,
        logic_version: DEFAULT_LOGIC_VERSION,
        validity_contract_version: dashboardMeta.validity_contract_version || DEFAULT_VALIDITY_CONTRACT_VERSION
      },
      pairs,
      trade_opportunities: pairs.filter((pair) => pair.decision === "TRADE"),
      avoid_today: pairs.filter((pair) => pair.decision !== "TRADE")
    };
  }

  function buildStoredLayer2DashboardFromRows(rows = [], options = {}) {
    const dashboardMeta = baseDashboardMeta(options.dashboard_meta || {});
    const buildNow = options.buildNow || new Date().toISOString();
    const pairs = rankTradeOpportunities(
      PAIRS.map((config) => {
        const selected = selectPreferredPairRows(rows, config, dashboardMeta, buildNow);
        return buildPairEntry(
          config,
          selected.target?.agent || null,
          selected.usd?.agent || null,
          dashboardMeta,
          buildNow
        );
      })
    );

    return {
      dashboard_meta: {
        last_updated_et: buildNow,
        source: "layer_2_trade_selection_agent",
        dashboard_source: DEFAULT_DASHBOARD_SOURCE,
        logic_version: DEFAULT_LOGIC_VERSION,
        validity_contract_version: dashboardMeta.validity_contract_version || DEFAULT_VALIDITY_CONTRACT_VERSION
      },
      pairs,
      trade_opportunities: pairs.filter((pair) => pair.decision === "TRADE"),
      avoid_today: pairs.filter((pair) => pair.decision !== "TRADE")
    };
  }

  return {
    DEFAULT_DASHBOARD_SOURCE,
    DEFAULT_LOGIC_VERSION,
    DEFAULT_VALIDITY_CONTRACT_VERSION,
    PAIRS,
    buildStoredLayer2DashboardFromAgents,
    buildStoredLayer2DashboardFromRows,
    candidateRowInfo,
    confidenceBucketFromValue,
    computeHeadlineConfidenceData,
    deriveLayer2PairSignal,
    latestRowForAsset,
    rowToAgent,
    selectPreferredPairRows
  };
});


